export type AdultPartId = BodyPartId;

export interface AdultPartDef {
  id: BodyPartId;
  percentage: number;
}

// Adult Rule of Nines — front/back split. Each surface counts independently.
export const ADULT_PARTS: AdultPartDef[] = [
  { id: 'head_front',      percentage: 4.5 },
